  'plan.item.L05': 'ทางกลับบ้าน: การเดินทางกลับและการกลับเข้าชั้นบรรยากาศแบบกระดอน',
  'plan.item.D01': 'แคตตาล็อกชิ้นส่วนจริง มีเครื่องยนต์ราว 45 แบบ นำมาจากจรวด 18 รุ่น ซึ่งจะถูกประกอบขึ้นใหม่จากแคตตาล็อกนี้',
  'plan.item.D02': 'ดัดแปลงจรวดจริง: ยืดท่อน เปลี่ยนเครื่องยนต์ เพิ่มจรวดเสริม',
  'plan.item.D03': 'ประกอบจากชิ้นส่วน พร้อมค่า Δv อัตราส่วนแรงขับต่อน้ำหนัก และสัดส่วนมวลแบบทันที และคำเตือนด้วยภาษาง่ายๆ',
  'plan.item.D04': 'ทดสอบก่อนบิน: การจุดเครื่องยนต์ทดสอบภาคพื้นดิน อุโมงค์ลม และการทบทวนความพร้อมก่อนบิน',
  'plan.item.D05': 'ออกแบบจากน้ำหนักบรรทุกและวงโคจร พร้อมการแบ่งท่อนที่เหมาะสมที่สุด',
  'plan.item.D06': 'ระบบย่อยของดาวเทียม: พลังงานเมื่ออยู่ในเงาโลก ระบบขับเคลื่อน การควบคุมท่าทาง ลิงก์วิทยุ กล้องถ่ายภาพ และแรงต้านอากาศที่กำหนดอายุวงโคจร',
  'plan.item.D07': 'ออกแบบจากความต้องการ: รอบการกลับมาถ่ายซ้ำ ความละเอียด อายุการใช้งาน และปริมาณข้อมูล',
