  'watch.beat.deployed': 'ปล่อยดาวเทียม',
  'watch.beat.failed': 'สูญเสียยาน',
  'watch.say.countdown': 'จรวดเติมเชื้อเพลิงเต็มและรออยู่บนฐานปล่อย เมื่อนับถึงศูนย์เครื่องยนต์จะจุดติด และจรวดจะยกตัวขึ้นเมื่อแรงขับมากกว่าน้ำหนักของมัน',
  'watch.say.liftoff': 'ทะยานขึ้นแล้ว! เครื่องยนต์ดันแรงกว่าน้ำหนักจรวด มันจึงลอยพ้นฐานปล่อย ช่วงแรกจะช้าเพราะยังหนักด้วยเชื้อเพลิงเต็มถัง',
  'watch.say.climb': 'จรวดไต่ขึ้นเกือบตรงดิ่ง เพื่อให้พ้นฐานปล่อยและผ่านชั้นอากาศที่หนาแน่นที่สุดไปให้ได้',
  'watch.say.maxQ': 'ช่วงแรงกดอากาศสูงสุด จรวดเร็วมากแล้วแต่อากาศยังหนาแน่น นี่จึงเป็นช่วงที่อากาศปะทะตัวจรวดแรงที่สุด',
  'watch.say.gravityTurn': 'จรวดค่อยๆ เอียงตัวลงหาขอบฟ้า เพราะการขึ้นสู่วงโคจรไม่ได้อยู่ที่ขึ้นให้สูงอย่างเดียว แต่ต้องพุ่งไปด้านข้างให้เร็วมากๆ',
  'watch.say.boosterSep': 'บูสเตอร์ด้านข้างใช้เชื้อเพลิงหมดแล้วจึงแยกตัวออก เมื่อทิ้งน้ำหนักเปล่าไป จรวดที่เหลือก็เร่งความเร็วได้ดีขึ้น',
  'watch.say.boosterSepCross': 'บูสเตอร์ทั้งสี่แยกตัวออกพร้อมกันและกางออกเป็นรูป “กากบาทโคโรเลฟ” อันโด่งดัง ส่วนท่อนกลางยังคงจุดเครื่องยนต์ต่อไป',
  'watch.say.boosterSepSolid': 'บูสเตอร์เชื้อเพลิงแข็งเผาไหม้หมดแล้ว มอเตอร์แยกตัวขนาดเล็กดันให้พ้นจากแกนกลางพร้อมกลุ่มควันขาว ส่วนทางควันหนาที่ทิ้งไว้จะลอยค้างอยู่บนฟ้าอีกหลายนาที',
  'watch.say.transonic': 'จรวดกำลังผ่านความเร็วเสียง ในอากาศชื้น อากาศที่เร่งผ่านส่วนหัวจะเย็นลงจนไอน้ำควบแน่น เกิดเป็นกลุ่มเมฆวาบขึ้นรอบตัวจรวดชั่วครู่',
  'watch.say.fairingSep': 'ฝาครอบหัวจรวดแยกออกเป็นสองซีกแล้วหลุดไป เพราะอากาศเบาบางมากจนไม่ต้องปกป้องดาวเทียมอีกแล้ว',
  'watch.say.stageSep': 'ทิ้งท่อนที่เชื้อเพลิงหมดแล้ว และท่อนถัดไปจุดเครื่องยนต์ต่อ จรวดจะทิ้งน้ำหนักไปเรื่อยๆ ระหว่างทาง',
  'watch.say.upperStage': 'เหนือชั้นบรรยากาศ จรวดท่อนบนยังเร่งความเร็วต่อ ต้องทำความเร็วให้ได้ราว 27,000 กม./ชม. จึงจะอยู่ในวงโคจรได้',
  'watch.say.coast': 'ดับเครื่องยนต์แล้ว ยานลอยขึ้นต่อเหมือนลูกบอลที่ถูกโยน ไปยังจุดสูงสุดของเส้นทาง ซึ่งจะจุดเครื่องยนต์อีกครั้ง',
  'watch.say.burn': 'เครื่องยนต์จุดอีกครั้งเพื่อเพิ่มความเร็ว ยกวงโคจรให้สูงขึ้นและกลมขึ้น',
  'watch.say.orbit': 'เข้าสู่วงโคจรแล้ว! ยานกำลังตกรอบโลกอยู่ตลอดเวลา แต่เร็วมากจนพื้นโลกโค้งหนีออกไปใต้ตัวมันตลอด',
  'watch.say.deployed': 'ดาวเทียมแยกตัวออกจากจรวดแล้ว และเริ่มต้นภารกิจของตัวเอง',
  'watch.say.failed': 'สูญเสียยานแล้ว จรวดจริงก็ล้มเหลวได้เช่นกัน และทุกความล้มเหลวคือบทเรียนของวิศวกร',
