  'dlg.physics.notationText': 'สัญลักษณ์เป็นไปตาม ISO 1151 (เลขมัคตาม ISO 80000) หรือ ГОСТ 20058-80 ตามที่เลือกในโหมดวิศวกร ค่าเริ่มต้นภาษารัสเซียใช้ ГОСТ ภาษาอังกฤษและไทยใช้ ISO ทั้งสองมาตรฐานให้แกน x ของลำตัวชี้ไปทางหัว ISO ให้แกน y ชี้ไปทางขวาและแกน z ชี้ลงทางท้อง ส่วน ГОСТ ให้แกน y ชี้ขึ้นและแกน z ชี้ไปทางขวา ดังนั้นอัตราเงยหัวเป็น +q ใน ISO และ +ωz ใน ГОСТ ส่วนอัตราหันหัวไปทางขวาเป็น +r ใน ISO แต่เป็น −ωy ใน ГОСТ อัตราหมุนและมุมแสดงตามแกนและเครื่องหมายของมาตรฐานที่ใช้อยู่ และคำนิยามด้านล่างเป็นของมาตรฐานนั้น',
