  'mc.intro': 'แต่ละรอบบินภารกิจในแผงตั้งค่าแบบ 6-DOF จนจบภารกิจ (ถึงวงโคจรเป้าหมายหลังการจุดเครื่องตามแผนครบทุกครั้ง) โดยสุ่มค่ากระจายด้านล่างของตัวเอง (แจกแจงปกติ 1σ ตามที่ตั้ง ตัดที่ 3σ แยกรายขั้นและกลุ่มบูสเตอร์) แล้วอ่านวงโคจรทั้งตอนจบภารกิจและตอนดับเครื่องช่วงขึ้น ภารกิจยังวางแผนบนจรวดค่าออกแบบ ส่วนจรวดที่เพี้ยนแล้วคือตัวที่บินจริง seed เดิมให้ค่าสุ่มชุดเดิมเสมอ ไม่ว่าจะปิดค่าใดหรือใช้กฎนำร่องแบบไหน',
